/**
 * ryoAirAttackFrames.ts
 *
 * Ryo Sakazaki air attack frames: AIR_A (3f), AIR_C (4f), AIR_D (4f).
 * 96x144 px, 24-color SNK palette.
 * Style target: SNK KOF2002 — clean outlines, multi-level inner shadows, warm palette.
 *
 * Anchor { x: 48, y: 144 } = ground reference point.
 * Airborne frames have character in upper portion, transparent space below.
 *
 * Encoding: '.' = transparent (0), '1'-'9' = palette 1-9, 'a'-'n' = palette 10-23
 */

export interface PixelFrame {
  width: number;
  height: number;
  palette: Record<number, string>;
  pixels: number[][];
  anchor: { x: number; y: number };
}

/* ---------- 24-color SNK palette ---------- */
const PALETTE: Record<number, string> = {
   0: 'transparent',
   1: '#080604',   // deepest outline
   2: '#1a1208',   // outline
   3: '#2a1c10',   // hair deepest
   4: '#3a2818',   // hair dark
   5: '#5a3a22',   // hair mid
   6: '#7a5030',   // hair light
   7: '#9a6840',   // hair highlight
   8: '#f5d0a0',   // skin light
   9: '#e8c090',   // skin mid-light
  10: '#d0a870',   // skin mid
  11: '#b89058',   // skin dark
  12: '#a07840',   // skin darker
  13: '#886030',   // skin darkest
  14: '#faf8f4',   // gi lightest
  15: '#f0ece4',   // gi light
  16: '#e0d8c8',   // gi mid-light
  17: '#d0c4b0',   // gi mid
  18: '#b8a898',   // gi dark
  19: '#a09484',   // gi darkest
  20: '#181410',   // belt / eyes black
  21: '#ffffff',   // eye white / highlight
  22: '#d83030',   // headband red
  23: '#a02020',   // headband dark red
};

const W = 96;
function r(s: string): number[] {
  const padded = s.padEnd(W, '.').slice(0, W);
  return padded.split('').map(ch => {
    if (ch === '.') return 0;
    if (ch >= '0' && ch <= '9') return ch.charCodeAt(0) - 48;
    if (ch >= 'a' && ch <= 'n') return ch.charCodeAt(0) - 87;
    return 0;
  });
}

